import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync,rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { request } from 'node:http';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { LocalAuth,sessionToken } from '../auth.js';
import jsQR from 'jsqr';
import { PNG } from 'pngjs';

test('세션 만료, 로그아웃 및 로그인 시도 제한',()=>{
  assert.throws(()=>new LocalAuth(''),/12자/);
  const auth=new LocalAuth('가상-관리자-암호-12345');
  assert.equal(auth.login('틀린 암호',1000),null);
  const token=auth.login('가상-관리자-암호-12345',2000);
  assert.equal(auth.valid(token,2001),true);assert.equal(auth.valid(token,2000+8*60*60*1000),false);
  const again=auth.login('가상-관리자-암호-12345',3000);auth.logout(again);assert.equal(auth.valid(again,3001),false);
  assert.equal(sessionToken('other=x; jweb_session=abc'),'abc');
  for(let i=0;i<10;i++)assert.equal(auth.login('wrong',4000+i),null);
  assert.equal(auth.login('가상-관리자-암호-12345',5000),null);
  assert.ok(auth.login('가상-관리자-암호-12345',4000+5*60*1000+20));
});

test('관리자 암호가 없으면 서버는 시작하지 않는다',async()=>{
  const dir=mkdtempSync(join(tmpdir(),'j-web-no-password-'));
  const env={...process.env,JWEB_DATA_DIR:dir};delete env.JWEB_ADMIN_PASSWORD;
  const child=spawn(process.execPath,['server.js'],{cwd:process.cwd(),env,stdio:['ignore','pipe','pipe']});
  try {
    let stderr='';child.stderr.on('data',chunk=>{stderr+=chunk;});
    const [code]=await once(child,'exit');
    assert.notEqual(code,0);assert.match(stderr,/관리자 암호/);
  } finally {rmSync(dir,{recursive:true,force:true});}
});

test('HTTPS 중계 주소는 QR과 보안 쿠키에 사용되고 다른 주소는 거절한다',async()=>{
  const dir=mkdtempSync(join(tmpdir(),'j-web-proxy-'));
  const reservation=createServer();await new Promise(resolve=>reservation.listen(0,'127.0.0.1',resolve));
  const port=reservation.address().port;await new Promise(resolve=>reservation.close(resolve));
  const child=spawn(process.execPath,['server.js'],{cwd:process.cwd(),env:{...process.env,PORT:String(port),JWEB_DATA_DIR:dir,JWEB_ADMIN_PASSWORD:'test-password-12345',JWEB_PUBLIC_ORIGIN:'https://example.test'},stdio:['ignore','pipe','pipe']});
  try{
    await Promise.race([once(child.stdout,'data'),once(child,'exit').then(()=>{throw new Error('시험 서버가 종료됐습니다.');})]);
    const base=`http://127.0.0.1:${port}`,headers={host:'example.test',origin:'https://example.test','content-type':'application/json'};
    const proxyRequest=(path,method='GET',extra={},payload='')=>new Promise((resolve,reject)=>{const req=request(`${base}${path}`,{method,headers:{...headers,...extra}},res=>{const chunks=[];res.on('data',chunk=>chunks.push(chunk));res.on('end',()=>resolve({status:res.statusCode,headers:res.headers,body:Buffer.concat(chunks).toString()}));});req.on('error',reject);req.end(payload);});
    assert.equal((await fetch(`${base}/api/session`)).status,403);
    assert.equal((await proxyRequest('/api/session','GET',{origin:'https://other.test'})).status,403);
    const login=await proxyRequest('/api/login','POST',{},JSON.stringify({password:'test-password-12345'}));assert.equal(login.status,200);assert.match(login.headers['set-cookie'][0],/; Secure/);
    const cookie=login.headers['set-cookie'][0].split(';')[0];
    const site=JSON.parse((await proxyRequest('/api/sites','POST',{cookie},JSON.stringify({name:'가상 현장'}))).body);
    const invite=JSON.parse((await proxyRequest(`/api/sites/${site.id}/invitation`,'POST',{cookie},'{}')).body);
    assert.match(invite.link,/^https:\/\/example\.test\/join\?token=/);
    const png=PNG.sync.read(Buffer.from(invite.image.split(',')[1],'base64'));assert.equal(jsQR(new Uint8ClampedArray(png.data),png.width,png.height)?.data,invite.link);
  }finally{child.kill();await once(child,'exit').catch(()=>{});rmSync(dir,{recursive:true,force:true});}
});

